// Next.js Frontend - example in a React component or service
import axios from 'axios';

interface Topic {
  title: string;
  description?: string;
}

interface UserPreferences {
  hours_per_week: number;
  study_weekends: boolean;
}

interface GenerateScheduleRequest {
  course_id: number;
  exam_date: string; // ISO format 'YYYY-MM-DD'
  topics: Topic[];
  user_preferences: UserPreferences;
}

interface GenerateScheduleResponse {
  success: boolean;
  session_count: number;
}

async function generateStudyPlan(data: GenerateScheduleRequest): Promise<GenerateScheduleResponse> {
  try {
    const response = await axios.post<GenerateScheduleResponse>(
      '/api/generate-schedule', // Proxy to FastAPI backend or direct call
      data,
      {
        headers: {
          Authorization: `Bearer ${yourJwtToken}`, // Include user's JWT token
        },
      }
    );
    return response.data;
  } catch (error) {
    console.error('Error generating study plan:', error);
    throw error; // Handle this in UI (AC7)
  }
}
